import Link from "next/link";
import { notFound } from "next/navigation";
import { Mail, Pencil, Phone } from "lucide-react";
import { getContactDetails } from "@/app/dashboard/crm-queries";
import { ArchiveRecordButton } from "@/components/crm/archive-record-button";
import { DetailSection, EmptyRelationship } from "@/components/crm/detail-section";
import { PageHeader } from "@/components/dashboard/page-header";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { hasWorkspacePermission } from "@/lib/authorization";
import { DEAL_STAGE_LABELS } from "@/lib/constants/crm";
import { formatCurrencyFromCents } from "@/lib/revenue";
import { getCurrentWorkspace } from "@/lib/workspaces";

export default async function ContactDetailPage({ params }: { params: Promise<{ id: string }> }) { const { id } = await params; const [data, workspace] = await Promise.all([getContactDetails(id), getCurrentWorkspace()]); if (!data) notFound(); const canUpdate = hasWorkspacePermission(workspace.role, "crm:update_all") || hasWorkspacePermission(workspace.role, "crm:update_assigned"); const canDelete = hasWorkspacePermission(workspace.role, "crm:delete"); return <div className="space-y-5"><PageHeader eyebrow="Contact" title={data.contact.fullName} description={data.contact.title ?? "Contact profile and connected CRM work."} action={<div className="flex gap-2">{canUpdate ? <Button asChild variant="outline"><Link href={`/dashboard/customers/contacts/${id}/edit`}><Pencil className="mr-2 h-4 w-4" />Edit</Link></Button> : null}{canDelete ? <ArchiveRecordButton id={id} kind="contact" /> : null}</div>} /><div className="grid gap-5 lg:grid-cols-3"><DetailSection title="Contact details"><dl className="space-y-3 text-sm"><div><dt className="text-muted-foreground">Email</dt><dd>{data.contact.email ? <a className="inline-flex items-center gap-1 text-primary" href={`mailto:${data.contact.email}`}><Mail className="h-3 w-3" />{data.contact.email}</a> : "—"}</dd></div><div><dt className="text-muted-foreground">Phone</dt><dd>{data.contact.phone ? <a className="inline-flex items-center gap-1 text-primary" href={`tel:${data.contact.phone}`}><Phone className="h-3 w-3" />{data.contact.phone}</a> : "—"}</dd></div><div><dt className="text-muted-foreground">Account</dt><dd>{data.contact.accountId && data.contact.accountName ? <Link className="text-primary" href={`/dashboard/customers/accounts/${data.contact.accountId}`}>{data.contact.accountName}</Link> : "—"}{data.contact.isPrimary ? <Badge className="ml-2" variant="secondary">Primary</Badge> : null}</dd></div><div><dt className="text-muted-foreground">Assigned owner</dt><dd>{data.contact.assignedOwnerUserId ?? "Unassigned"}</dd></div></dl></DetailSection><div className="space-y-5 lg:col-span-2"><DetailSection title="Related deals">{data.relatedDeals.length ? <div className="space-y-3">{data.relatedDeals.map((deal) => <div key={deal.id} className="flex justify-between rounded-2xl border p-3"><div><Link href={`/dashboard/deals/${deal.id}`} className="font-medium hover:text-primary">{deal.name}</Link><p className="text-sm text-muted-foreground">{DEAL_STAGE_LABELS[deal.stage]}</p></div><b>{formatCurrencyFromCents(deal.valueCents, deal.currency)}</b></div>)}</div> : <EmptyRelationship>No visible deals are connected to this contact.</EmptyRelationship>}</DetailSection><DetailSection title="Related leads">{data.relatedLeads.length ? <ul className="space-y-2">{data.relatedLeads.map((lead) => <li key={lead.id}><Link href={`/dashboard/leads/${lead.id}`} className="font-medium hover:text-primary">{lead.fullName}</Link><span className="ml-2 text-sm text-muted-foreground">{lead.status}</span></li>)}</ul> : <EmptyRelationship>No visible leads are connected to this contact.</EmptyRelationship>}</DetailSection></div></div><div className="grid gap-5 lg:grid-cols-2"><DetailSection title="Open tasks">{data.openTasks.length ? <ul className="space-y-2">{data.openTasks.map((task) => <li key={task.id}><span className="font-medium text-sm">{task.title}</span><span className="ml-2 text-xs text-muted-foreground">{task.dueAt?.toLocaleDateString() ?? "No due date"}</span></li>)}</ul> : <EmptyRelationship>No open tasks are linked to this contact.</EmptyRelationship>}</DetailSection><DetailSection title="Recent activity">{data.events.length ? <ul className="space-y-3">{data.events.map((event) => <li key={event.id} className="border-l-2 pl-3 text-sm"><p>{event.message}</p><p className="mt-1 text-xs text-muted-foreground">{event.createdAt.toLocaleString()}</p></li>)}</ul> : <EmptyRelationship>No contact activity yet.</EmptyRelationship>}</DetailSection></div></div>; }
